// Cutting Words / Острые Слова (Дар Слаанеш, wdbc-1rno).
// Книга: победив в ЛЮБОМ тесте социального взаимодействия, чемпион может
// нанести проигравшему 1d5+Успехи непоглощаемого R Dmg в торс (кровавые
// стигматы). Сам тест мог быть обычным, встречным или расширенным — победа
// и число Успехов уже показаны в карточке только что брошенного теста;
// движку нечем это перепроверить (нет привязки "этот тест был социальным
// взаимодействием И только что выигран этим актором"), поэтому число
// Успехов вводит игрок честно, как в карточке, шкалой книги.
const targetDoc = game.user.targets?.first?.() ?? [...(game.user.targets ?? [])][0];
const targetActor = (targetDoc?.document ?? targetDoc)?.actor;
if (!targetActor) {
  ui.notifications?.warn("Острые Слова: выберите проигравшего тест.");
} else {
  const STEPS = [["0", "0 Успехов"], ["1", "1 Успех"], ["2", "2 Успеха"], ["3", "3 Успеха"], ["4", "4 Успеха"], ["5", "5+ Успехов"]];
  const choice = await foundry.applications.api.DialogV2.wait({
    window: { title: "Острые Слова — число Успехов" },
    content: `<p>Сколько Успехов было на только что выигранном тесте социального взаимодействия против ${targetActor.name}?</p>`,
    buttons: STEPS.map(([action, label]) => ({ action, label })),
    rejectClose: false
  });
  if (choice !== null && choice !== undefined) {
    const successes = Number(choice) || 0;
    const roll = await new Roll(`1d5+${successes}`).evaluate();
    await targetActor.update(woundLossUpdates(targetActor.system, roll.total));
    await ChatMessage.create(ChatMessage.applyRollMode({
      speaker,
      content: `<div class="wh-roll-result">
        <div class="roll-header">Острые Слова — ${actor.name} → ${targetActor.name}</div>
        <div class="roll-threshold">1d5+${successes} Успехов — <b>${roll.total}</b> непоглощаемого урона в торс (кровавые стигматы).</div>
      </div>`,
      rolls: [roll]
    }, game.settings.get("core", "rollMode")));
  }
}
